// Header glyph of the chooser, as a pixel hash of the icon above the green rule.
// The reference is a T3j screenshot. pageTitle is not involved.
// Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const REF = 'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c1-zone-open.png';
const OTHERS = [
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c2-zone-open.png',
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c1-2154-open.png',
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-control-2154-open.png',
  'work/out/accept-k1-c1-zone-open.png',
  'work/out/accept-k1-c2-zone-open.png',
];

function readPng(file) {
  const data = readFileSync(file);
  if (data.readUInt32BE(0) !== 0x89504e47) throw new Error('not a png: ' + file);
  const width = data.readUInt32BE(16);
  const height = data.readUInt32BE(20);
  const idat = [];
  for (let pos = 8; pos < data.length;) {
    const length = data.readUInt32BE(pos);
    const kind = data.toString('latin1', pos + 4, pos + 8);
    if (kind === 'IDAT') idat.push(data.subarray(pos + 8, pos + 8 + length));
    pos += 12 + length;
    if (kind === 'IEND') break;
  }
  const raw = inflateSync(Buffer.concat(idat));
  const rows = [];
  const stride = width * 3;
  for (let y = 0; y < height; y++) {
    if (raw[(stride + 1) * y] !== 0) throw new Error('png filter is not 0 in ' + file);
    rows.push(raw.subarray((stride + 1) * y + 1, (stride + 1) * y + 1 + stride));
  }
  return { width, height, rows };
}

function pixel(row, x) {
  return [row[x * 3], row[x * 3 + 1], row[x * 3 + 2]];
}

function nearBlack(p) {
  return p[0] < 16 && p[1] < 16 && p[2] < 16;
}

function greenRow(img) {
  for (let y = 0; y < Math.min(img.height, 80); y++) {
    let n = 0;
    for (let x = 0; x < img.width; x++) {
      const p = pixel(img.rows[y], x);
      if (p[1] > 80 && p[0] < 40 && p[2] < 40) n += 1;
    }
    if (n > img.width * 0.4) return y;
  }
  return null;
}

function iconBox(img, limitY) {
  let x0 = img.width;
  let y0 = limitY;
  let x1 = -1;
  let y1 = -1;
  let n = 0;
  for (let y = 0; y < limitY; y++) {
    for (let x = 0; x < img.width; x++) {
      if (nearBlack(pixel(img.rows[y], x))) continue;
      n += 1;
      if (x < x0) x0 = x;
      if (y < y0) y0 = y;
      if (x > x1) x1 = x;
      if (y > y1) y1 = y;
    }
  }
  if (n === 0) return null;
  return { x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1, pixels: n };
}

function hashRect(img, rect) {
  const parts = [];
  for (let y = rect.y; y < rect.y + rect.h; y++) {
    parts.push(img.rows[y].subarray(rect.x * 3, (rect.x + rect.w) * 3));
  }
  return createHash('sha256').update(Buffer.concat(parts)).digest('hex');
}

function textsOf(id) {
  const out = [];
  for (const line of readFileSync('work/out/accept-k1.jsonl', 'utf8').split(/\n/)) {
    if (!line.includes('"id":"' + id + '"')) continue;
    const rec = JSON.parse(line);
    if (rec.id !== id) continue;
    out.push({
      session: rec.session,
      title: rec.actual && rec.actual.title,
      helpText: rec.actual && rec.actual.helpText,
      texts: rec.actual && rec.actual.texts,
      highlight: rec.actual && rec.actual.highlight,
    });
  }
  return out;
}

const refImg = readPng(REF);
const rule = greenRow(refImg);
if (rule === null) throw new Error('no green rule on the reference');
const box = iconBox(refImg, rule);
if (!box) throw new Error('no header icon above the green rule');
const refHash = hashRect(refImg, box);
const files = [{ file: REF, img: refImg, hash: refHash, match: true }];
for (const file of OTHERS) {
  const img = readPng(file);
  const same = img.width === refImg.width && img.height === refImg.height;
  const hash = same ? hashRect(img, box) : null;
  files.push({ file, width: img.width, height: img.height, hash, match: hash === refHash });
}
const doc = {
  reference: REF,
  width: refImg.width,
  height: refImg.height,
  greenRow: rule,
  rect: { x: box.x, y: box.y, w: box.w, h: box.h },
  pixels: box.pixels,
  sha256: refHash,
  files,
  chooserTexts: {
    '2154-open': textsOf('2154-open'),
    'zone-open': textsOf('zone-open'),
  },
  note: 'The hash is the header icon above the green rule. It is not derived from the help sentence.',
};
writeFileSync('work/out/header-ref-c1.json', JSON.stringify(doc, null, 2) + '\n');
console.log(JSON.stringify({
  width: doc.width,
  height: doc.height,
  greenRow: rule,
  rect: doc.rect,
  pixels: box.pixels,
  sha256: refHash,
  matches: files.map((f) => ({ file: f.file, match: f.match })),
  zoneTexts: doc.chooserTexts['zone-open'].slice(0, 1),
  helpTexts: doc.chooserTexts['2154-open'].slice(0, 1),
}, null, 2));
